-- Consolidates the add/edit item flow to a single field (was brand + drink
-- name + flavor) by moving the product catalog from a static, unstructured
-- src/lib/products.js array (combined name strings like "White Claw Black
-- Cherry") into a real table with brand/drink_name/flavor already split out
-- for the hand-curated beer/seltzer/cider entries. Liquor entries (~2000,
-- auto-generated from Iowa's public dataset) have no reliable brand
-- boundary and stay as unstructured single strings (brand/flavor null) —
-- deliberately deferred, not an oversight; see CLAUDE.md.
--
-- Reference data, not owned by any inventory/user — read-only from the
-- client. Seeding/regeneration happens via reviewed SQL applied directly
-- (scripts/seed-products-catalog.mjs for this initial seed,
-- scripts/generate-products.js going forward for liquor regeneration),
-- same trust level as every other schema change in this repo.

create table public.products (
  id           uuid primary key default gen_random_uuid(),
  brand        text,
  drink_name   text not null,
  flavor       text,
  type         text not null check (type in ('beer','seltzer','cider','liquor','other')),
  default_unit text,
  default_size text,
  is_generated boolean not null default false,
  created_at   timestamptz not null default now()
);
alter table public.products enable row level security;
create policy "products_select_authenticated" on public.products for select
  using (auth.role() = 'authenticated');

-- Lets a drink row reference the catalog entry it was added/edited from —
-- set when a suggestion is picked, left null for free-typed/novel entries
-- (same spirit as brand already being nullable for that case).
alter table public.drinks add column product_id uuid references public.products(id) on delete set null;

-- Auto-generated by scripts/seed-products-catalog.mjs — do not hand-edit.
